from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            separators.append(("h", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            separators.append(("v", c))
    if not separators:
        raise ValueError("No solid separator found")
    orient, idx = min(separators, key=lambda s: abs((h if s[0] == "h" else w) - 2 * s[1] - 1))
    if orient == "h":
        a, b = grid[:idx], grid[idx + 1:]
    else:
        a = [row[:idx] for row in grid]
        b = [row[idx + 1:] for row in grid]
    ph, pw = min(len(a), len(b)), min(len(a[0]), len(b[0]))
    a = [row[:pw] for row in a[:ph]]
    b = [row[:pw] for row in b[:ph]]
    background = Counter(v for row in a for v in row).most_common(1)[0][0]
    return [[3 if a[r][c] == b[r][c] else background for c in range(pw)]
            for r in range(ph)]


