def transform(grid):
    """Project the sparse interior marker color inward from colored edge bars."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    edge_counts = {}
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] != background:
                edge_counts[grid[r][c]] = edge_counts.get(grid[r][c], 0) + 1
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] != background:
                edge_counts[grid[r][c]] = edge_counts.get(grid[r][c], 0) + 1
    if not edge_counts:
        return out
    border_color = max(edge_counts, key=edge_counts.get)
    marker_colors = [v for v in counts if v != background and v != border_color]
    if not marker_colors:
        return out
    marker_color = max(marker_colors, key=lambda v: counts[v])

    launches = []
    for c in range(w):
        if grid[0][c] == border_color:
            launches.append((0, c, 1, 0))
        if grid[h - 1][c] == border_color:
            launches.append((h - 1, c, -1, 0))
    for r in range(h):
        if grid[r][0] == border_color:
            launches.append((r, 0, 0, 1))
        if grid[r][w - 1] == border_color:
            launches.append((r, w - 1, 0, -1))

    for r, c, dr, dc in launches:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == background:
                out[rr][cc] = marker_color
            elif out[rr][cc] == marker_color:
                out[rr][cc] = 4
                break
            else:
                break
            rr += dr
            cc += dc
    return out


