def transform(grid):
    """Project sparse markers through matching offsets of opposite edge bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Locate a single contiguous non-background bar on each opposite edge.
    def edge_run(axis, edge):
        n = w if axis == "horizontal" else h
        coords = [(0, i) if axis == "horizontal" and edge == 0 else
                  (h - 1, i) if axis == "horizontal" else
                  (i, 0) if edge == 0 else (i, w - 1)
                  for i in range(n)]
        vals = [grid[r][c] for r, c in coords]
        colors = [v for v in set(vals) if v != background]
        if not colors:
            return None
        color = max(colors, key=lambda v: vals.count(v))
        inds = [i for i, v in enumerate(vals) if v == color]
        if not inds or inds != list(range(min(inds), max(inds) + 1)):
            return None
        return color, min(inds), max(inds) + 1

    horizontal = (edge_run("horizontal", 0), edge_run("horizontal", 1))
    vertical = (edge_run("vertical", 0), edge_run("vertical", 1))
    if all(horizontal) and horizontal[0][0] == horizontal[1][0]:
        axis, bars = "horizontal", horizontal
    elif all(vertical) and vertical[0][0] == vertical[1][0]:
        axis, bars = "vertical", vertical
    else:
        return out

    border_color = bars[0][0]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != border_color]
    if not markers:
        return out

    # A marker within one edge run selects its within-run offset. The matching
    # offset of the opposite run is projected across the interior. Long (5+)
    # launch bars additionally project from their own edge to the marker.
    for r, c, color in markers:
        pos = c if axis == "horizontal" else r
        source = None
        for bar_index, (_, start, stop) in enumerate(bars):
            if start <= pos < stop:
                source = bar_index
                break
        out[r][c] = 4
        if source is None:
            continue
        _, source_start, source_stop = bars[source]
        other = bars[1 - source]
        offset = pos - source_start
        mapped = other[1] + offset
        if mapped >= other[2]:
            continue

        if axis == "horizontal":
            # Horizontal bars on top/bottom project a vertical line at the
            # corresponding coordinate of the opposite bar.
            for rr in range(h):
                if grid[rr][mapped] == background:
                    out[rr][mapped] = color
                elif grid[rr][mapped] != border_color and (rr, mapped) != (r, c):
                    out[rr][mapped] = 4
            if source_stop - source_start >= 5:
                edge_row = 0 if source == 0 else h - 1
                step = 1 if edge_row == 0 else -1
                rr = edge_row + step
                while 0 <= rr < h and (rr, c) != (r, c):
                    if grid[rr][c] == background:
                        out[rr][c] = color
                    rr += step
        else:
            # Vertical bars on left/right project a horizontal line at the
            # corresponding coordinate of the opposite bar.
            for cc in range(w):
                if grid[r if False else mapped][cc] == background:
                    out[mapped][cc] = color
                elif grid[mapped][cc] != border_color and (mapped, cc) != (r, c):
                    out[mapped][cc] = 4
            if source_stop - source_start >= 5:
                edge_col = 0 if source == 0 else w - 1
                step = 1 if edge_col == 0 else -1
                cc = edge_col + step
                while 0 <= cc < w and (r, cc) != (r, c):
                    if grid[r][cc] == background:
                        out[r][cc] = color
                    cc += step
    return out


