    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def run(axis, edge):
        n = w if axis == "h" else h
        if axis == "h":
            cells = [(0, i) if edge == 0 else (h - 1, i) for i in range(n)]
        else:
            cells = [(i, 0) if edge == 0 else (i, w - 1) for i in range(n)]
        colors = [grid[r][c] for r, c in cells if grid[r][c] != background]
        if not colors:
            return None
        color = max(set(colors), key=colors.count)
        inds = [i for i, (r, c) in enumerate(cells) if grid[r][c] == color]
        if not inds or inds != list(range(min(inds), max(inds) + 1)):
            return None
        return color, min(inds), max(inds) + 1

    for axis, edges in (("h", (run("h", 0), run("h", 1))),
                        ("v", (run("v", 0), run("v", 1)))):
        if not all(edges) or edges[0][0] != edges[1][0]:
            continue
        bar_color = edges[0][0]
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != background and grid[r][c] != bar_color]
        if not markers:
            return out
        for r, c, color in markers:
            pos = c if axis == "h" else r
            source = next((i for i, (_, lo, hi) in enumerate(edges)
                           if lo <= pos < hi), None)
            if source is None:
                continue
            lo, hi = edges[source][1:]
            other_lo, other_hi = edges[1 - source][1:]
            mapped = other_lo + pos - lo
            if mapped >= other_hi:
                continue
            out[r][c] = 4
            # Ray from the matching boundary bar cell to the sparse marker.
            if axis == "h":
                edge_row, step = (0, 1) if source == 0 else (h - 1, -1)
                rr = edge_row + step
                while 0 <= rr < h:
                    if (rr, c) == (r, c):
                        out[rr][c] = 4
                        break
                    if grid[rr][c] == background:
                        out[rr][c] = color
                    rr += step
                # Full projected ray at the corresponding offset in opposite bar.
                for rr in range(h):
                    if grid[rr][mapped] == background:
                        out[rr][mapped] = color
                    elif grid[rr][mapped] != bar_color and grid[rr][mapped] != background:
                        out[rr][mapped] = 4
            else:
                edge_col, step = (0, 1) if source == 0 else (w - 1, -1)
                cc = edge_col + step
                while 0 <= cc < w:
                    if (r, cc) == (r, c):
                        out[r][cc] = 4
