                    if grid[r][cc] == background:
                        out[r][cc] = color
                    cc += step
                for cc in range(w):
                    if grid[mapped][cc] == background:
                        out[mapped][cc] = color
                    elif grid[mapped][cc] != bar_color and grid[mapped][cc] != background:
                        out[mapped][cc] = 4
        return out
    return out

