    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find equal-color bars on a pair of opposite borders.
    def border_run(horizontal, edge):
        n = w if horizontal else h
        if horizontal:
            r = 0 if edge == 0 else h - 1
            vals = [grid[r][c] for c in range(w)]
        else:
            c = 0 if edge == 0 else w - 1
            vals = [grid[r][c] for r in range(h)]
        nonbg = [i for i, v in enumerate(vals) if v != background]
        if not nonbg:
            return None
        color = max((vals[i] for i in nonbg), key=lambda x: vals.count(x))
        positions = [i for i, v in enumerate(vals) if v == color]
        lo, hi = min(positions), max(positions) + 1
        if positions != list(range(lo, hi)):
            return None
        return color, lo, hi

    orientation = None
    bars = None
    for horizontal in (True, False):
        candidate = [border_run(horizontal, 0), border_run(horizontal, 1)]
        if all(candidate) and candidate[0][0] == candidate[1][0]:
            orientation, bars = horizontal, candidate
            break
    if bars is None:
        return [row[:] for row in grid]

    border_color = bars[0][0]
    other = [v for v in counts if v not in (background, border_color)]
    if not other:
        return [row[:] for row in grid]
    paint = max(other, key=lambda v: counts[v])
    out = [row[:] for row in grid]

    for edge, (_, lo, hi) in enumerate(bars):
        length = hi - lo
        for pos in range(lo, hi):
            # The middle bar cell is the divider; corner cells cannot launch.
            if length % 2 == 1 and pos == lo + length // 2:
                continue
            if orientation:
                r = 0 if edge == 0 else h - 1
                c = pos
                if (r, c) in ((0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)):
                    continue
                step = 1 if edge == 0 else -1
                rr = r + step
                while 0 <= rr < h:
                    value = grid[rr][c]
                    if value == paint:
                        out[rr][c] = 4
                        break
                    if value != background and value != border_color:
                        break
                    out[rr][c] = paint
                    rr += step
            else:
                r = pos
                c = 0 if edge == 0 else w - 1
                if (r, c) in ((0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)):
                    continue
                step = 1 if edge == 0 else -1
                cc = c + step
                while 0 <= cc < w:
                    value = grid[r][cc]
                    if value == paint:
                        out[r][cc] = 4
                        break
                    if value != background and value != border_color:
