    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Border runs act as directional ray launchers. Detect runs on each side
    # independently because the examples may use perpendicular bar pairs.
    tokens = []
    for r in (0, h - 1):
        nonbg = [c for c in range(w) if grid[r][c] != background]
        if nonbg:
            color = grid[r][nonbg[0]]
            lo, hi = min(nonbg), max(nonbg) + 1
            if all(grid[r][c] == color for c in range(lo, hi)):
                tokens.append(("horizontal", r, lo, hi, color))
    for c in (0, w - 1):
        nonbg = [r for r in range(h) if grid[r][c] != background]
        if nonbg:
            color = grid[nonbg[0]][c]
            lo, hi = min(nonbg), max(nonbg) + 1
            if all(grid[r][c] == color for r in range(lo, hi)):
                tokens.append(("vertical", c, lo, hi, color))

    if not tokens:
        return [row[:] for row in grid]
    bar_colors = {token[4] for token in tokens}
    candidates = [v for v in counts if v != background and v not in bar_colors]
    if not candidates:
        return [row[:] for row in grid]
    paint = max(candidates, key=lambda v: counts[v])
    out = [row[:] for row in grid]

    def ray(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == paint:
                out[r][c] = 4
                break
            if value != background:
                break
            out[r][c] = paint
            r += dr
            c += dc

    for axis, fixed, lo, hi, color in tokens:
        length = hi - lo
        if axis == "horizontal":
            # Long horizontal strips have two endpoint rays. Short pairs
            # have a single ray from the first cell.
            launch = [lo, hi - 1] if length >= 5 else [lo]
            for c in launch:
                dr = 1 if fixed == 0 else -1
                ray(fixed + dr, c, dr, 0)
        else:
            # The vertical two-cell token launches from its lower cell.
            r = hi - 1
            dc = 1 if fixed == 0 else -1
            ray(r, fixed + dc, 0, dc)
