def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    color = max((v for v in counts if v != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete horizontal top and bottom edges of the marked frame.
    for r in (r0, r1):
        for c in range(c0, c1 + 1):
            if out[r][c] == background:
                out[r][c] = 2

    # Repeated vertically aligned markers define a full vertical stroke across
    # the marked object's bounds; preserve the original marker cells.
    for c in range(c0, c1 + 1):
        rows = [r for r in range(r0, r1 + 1) if grid[r][c] == color]
        if len(rows) >= 2:
            for r in range(r0, r1 + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out

