def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    color = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # Between consecutive same-colored markers on a row or column, fill the
    # gap with 2; retain existing markers and all other cells.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

