def transform(grid):
    # Find the one shape color that appears in a sparse motif and in a connected
    # repeated object; the 2-valued shape encodes how to recolor the 0 targets.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The 2-colored object defines the stamp shape; normalize its bounding box.
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not cells:
        return g
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    motif = [(r-r0, c-c0) for r, c in cells]
    # Color 0 targets wherever the 2 motif fits (preserving nonzero cells).
    for r in range(h):
        for c in range(w):
            pts = [(r+dr, c+dc) for dr, dc in motif]
            if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0 for rr, cc in pts):
                for rr, cc in pts:
                    g[rr][cc] = 2
    return g

