        if corner == "tl":
            # The target lies to the right of the vertical arm.
            if b0 > c0:
                horizontal_gap = b0 - c0 - 1
                vertical_gap = max(r0 - a1 - 1, a0 - r1 - 1, 0)
                candidates.append((horizontal_gap + vertical_gap, cells))
        elif corner == "br":
            # The target lies to the right of the vertical arm, near its span.
