            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, r1, c1, -1, -1),
        ]
        for shape, er, ec, dr, dc in candidates:
            if pts == shape:
                ls.append((len(cells), i, color, er, ec, dr, dc))
                break
    if not ls:
        return [row[:] for row in grid]

    _, source_i, source_color, er, ec, dr, dc = max(ls)
    target_candidates = []
    for i, (color, cells) in enumerate(comps):
        if i == source_i or color == bg:
            continue
