            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, 1, 1),
        )
        matched = next(((dr, dc) for shape, dr, dc in patterns if shape == pts), None)
        if matched is None:
            continue
        dr, dc = matched
        candidates = []
        for j, (other_color, other_cells) in enumerate(comps):
