                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            comps.append((color, cells))

    out = [row[:] for row in grid]
    # A single pixel object is a marker. Its color indicates the palette
    # replacement for all other objects of that color.
    counts = Counter(color for color, cells in comps for _ in cells)
    marker_colors = {color for color, cells in comps if len(cells) == 1 and color != bg}
    for marker in marker_colors:
        # Demos show each singleton marker replaces the color with which it is paired.
        for color, cells in comps:
            if color == bg or color == marker or len(cells) <= 1:
                continue
            # The indicated targets are all components of the most frequent
            # non-background color, determined by the singleton's counterpart.
            if color == max((x for x in counts if x != bg), key=lambda x: counts[x]):
                for r, c in cells:
                    out[r][c] = marker
    return out


