def transform(grid):
    h, w = len(grid), len(grid[0])

    def mode(values):
        color, count = Counter(values).most_common(1)[0]
        return color, count / len(values)

    row_modes = [mode(row) for row in grid]
    # Rows dominated by the separator color form the horizontal frame.
    sep_rows = [r for r, (color, fraction) in enumerate(row_modes) if fraction >= 0.75]
    if len(sep_rows) < 2:
        return [row[:] for row in grid]
    body_rows = [r for r in range(h) if r not in set(sep_rows)]
    body_bg = Counter(grid[r][c] for r in body_rows for c in range(w)).most_common(1)[0][0]

    # Vertical frame lines share the dominant color of separator rows.
    sep_color = Counter(row_modes[r][0] for r in sep_rows).most_common(1)[0][0]
    sep_cols = []
    for c in range(w):
        color, frac = mode([grid[r][c] for r in body_rows])
        if color == sep_color and frac >= 0.75:
            sep_cols.append(c)
    if len(sep_cols) < 2:
        return [row[:] for row in grid]

    # In the demonstrated encoding the rightmost line merely closes the grid,
    # and the leftmost starts it; output cells correspond to frame intersections.
    # Recover each cell from the value represented consistently at the four
    # corners of its rectangular grid panel.
    out = []
    for r1, r2 in zip(sep_rows, sep_rows[1:]):
        row = []
        for c1, c2 in zip(sep_cols, sep_cols[1:]):
            # For staggered markers, the panel's value is the most frequent
            # non-background color at its four intersections (or background).
            values = [grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]]
            counts = Counter(v for v in values if v != body_bg)
            if not counts:
                row.append(body_bg)
            else:
                color, count = counts.most_common(1)[0]
                row.append(color if count >= 2 else body_bg)
        out.append(row)
    # A trailing frame line creates an extra empty interval in some layouts;
    # trim only columns that are entirely the body background.
    while out and len(out[0]) > 1 and all(row[-1] == body_bg for row in out):
        for row in out:
            row.pop()
    return out

