    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out

    colors = {value for row in grid for value in row}
    background = max(colors, key=lambda value: sum(row.count(value) for row in grid))

    for r, row in enumerate(grid):
        last = max((c for c, value in enumerate(row) if value != background), default=-1)
