def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        # Preserve the observed pattern and extrapolate the periodic suffix.
        end = w
        while end and row[end - 1] == bg:
            end -= 1
        n = end
        if n < 2 or end == w:
            continue
        # Candidate period: shortest repeated suffix; otherwise use the last transition pair.
        period = next((p for p in range(1, n // 2 + 1)
                       if row[n-2*p:n-p] == row[n-p:n]), None)
        if period is None:
            period = 2
        for c in range(end, w):
            if row[n-period + (c-end) % period] != bg:
                out[r][c] = 1
    return out

